import io,gzip,base64,zipfile
import pandas as pd,numpy as np,streamlit as st

st.set_page_config(page_title="V6.16 Pair Number Professor",page_icon="🧠",layout="wide")
st.title("🧠 V6.16 — GERÇEK PAIR/SAYI BULUCU PROFESÖRÜ")
st.success("KAPSAM: hareket tahmini doğru olan 152 ateşleme çekilişi. ZERO-UPLOAD.")
st.caption("Pair seçici, her test çekilişinden önce yalnız daha eski çekilişlerdeki PRE-H özellik→exact pair isabet ilişkisini öğrenir.")

DATA=""""""
FEATURES=['H3_state', 'H2_state', 'H1_state', 'corridor_silent_H3_H1', 'same_pair_seen_11_same_day', 'Q2_GATE_FROZEN', 'H1_sum', 'pre_total_blocks', 'H3_block_count', 'H2_block_count', 'H1_block_count', 'H3_max_len', 'H2_max_len', 'H1_max_len', 'block_count_delta_32', 'block_count_delta_21', 'max_len_delta_32', 'max_len_delta_21']

def load():
    return pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(DATA))))

d=load().sort_values(["draw_no","pair"]).reset_index(drop=True)
if d.draw_no.nunique()!=152:
    st.error(f"Kapsam hatası: {d.draw_no.nunique()} çekiliş okundu, 152 bekleniyordu."); st.stop()

# categorical PRE-H state path + numeric pre features. Simple empirical hierarchical learner.
d["state_key"]=d["H3_state"].astype(str)+">"+d["H2_state"].astype(str)+">"+d["H1_state"].astype(str)
draws=sorted(d.draw_no.unique())
warmup=50
rows=[]

for pos in range(warmup,len(draws)):
    target=draws[pos]
    tr=d[d.draw_no<target]
    te=d[d.draw_no==target].copy()

    # learn state-path hit rates strictly from past
    a=tr.groupby("state_key").y.agg(["count","sum"]).reset_index()
    a["state_rate"]=(a["sum"]+1)/(a["count"]+2)
    te=te.merge(a[["state_key","count","state_rate"]],on="state_key",how="left")
    global_rate=(tr.y.sum()+1)/(len(tr)+2)
    te["state_rate"]=te["state_rate"].fillna(global_rate)
    te["count"]=te["count"].fillna(0)

    # pair-specific historical exact hit rate strictly from past
    b=tr.groupby("pair").y.agg(["count","sum"]).reset_index()
    b["pair_rate"]=(b["sum"]+1)/(b["count"]+2)
    te=te.merge(b[["pair","pair_rate"]],on="pair",how="left")
    te["pair_rate"]=te["pair_rate"].fillna(global_rate)

    # PRE-H structural support, no H outcome.
    te["struct"]=(
        0.20*pd.to_numeric(te["H1_sum"],errors="coerce").fillna(0) +
        0.12*pd.to_numeric(te["Q2_GATE_FROZEN"],errors="coerce").fillna(0) +
        0.08*pd.to_numeric(te["corridor_silent_H3_H1"],errors="coerce").fillna(0)
    )
    te["score"]=0.55*te.state_rate+0.35*te.pair_rate+0.10*te.struct
    te=te.sort_values(["score","pair"],ascending=[False,True])

    for k in [1,2,3,4,5,8,10]:
        s=te.head(k); hits=int(s.y.sum())
        rows.append({"draw_no":int(target),"K":k,"predicted":len(s),"hits":hits,
                     "at_least_one":int(hits>0),"all_hit":int(len(s)>0 and hits==len(s))})

r=pd.DataFrame(rows)
summ=r.groupby("K").agg(test_draws=("draw_no","count"),predicted=("predicted","sum"),
 exact_hits=("hits","sum"),draws_with_hit=("at_least_one","sum"),all_hit_draws=("all_hit","sum")).reset_index()
summ["precision"]=summ.exact_hits/summ.predicted
summ["draw_hit_rate"]=summ.draws_with_hit/summ.test_draws

st.metric("Kronolojik öğrenme",f"ilk {warmup} çekiliş geçmiş / sonraki {len(draws)-warmup} kör ileri test")
st.dataframe(summ,use_container_width=True,hide_index=True)

bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
    z.writestr("00_MANIFEST.txt","V6.16 PAIR NUMBER PROFESSOR\n152 movement-correct gate draw. First 50 warmup, remaining chronological blind forward. H target used only as historical label.\n")
    z.writestr("01_WALK_FORWARD_AUDIT.csv",r.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("02_SUMMARY.csv",summ.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ V6.16 TEK ZIP",bio.getvalue(),"HIZLI_ON_V6_16_PAIR_NUMBER_PROFESSOR.zip","application/zip",use_container_width=True)
